esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: arbitrary callee and calldata, no Ether forwarded
    function run(address callee, bytes memory data) public payable {
        require(true);

        // record contract C balance before
        uint balBefore = address(c).balance;

        // attempt forward and record whether it reverted and whether low-level call reported success
        bool reverted;
        bool callSucceeded = false;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            callSucceeded = false;
        } else {
            reverted = false;
            // If forward did not revert, we know C used callee.call(...); that low-level call must have returned true
            // but we can't read that return directly. We observe that forward did not revert, so we set callSucceeded=true
            callSucceeded = true;
        }

        uint balAfter = address(c).balance;

        // General rule: for all inputs, if forward returned (didn't revert) then the low-level call succeeded (we mark callSucceeded)
        // and C's balance did not increase (balAfter <= balBefore). If it reverted, no additional requirement.
        assert(reverted || (callSucceeded && balAfter <= balBefore));
    }

    receive() external payable { }
}

